import subprocess, json, sys, unicodedata
from collections import Counter, defaultdict

def run_json(cmd):
    out = subprocess.check_output(cmd, text=True)
    try:
        return json.loads(out)
    except Exception as e:
        print('JSON parse error for', cmd, 'out=', out[:500], file=sys.stderr)
        raise

def run_text_json(cmd):
    return run_json(cmd)

# fetch 35 recent chats
convs=[]
for off in range(0,35,5):
    data=run_json(['chats','list-recent-conversations','--offset',str(off),'--limit','5','--limit-recent-messages-per-conversation','0'])
    convs.extend(data)
convs=convs[:35]
print('num convs', len(convs), file=sys.stderr)
# fetch all contacts
contacts=[]
meta_total=None
for off in range(0,200,10):
    data=run_json(['contacts','get-contacts','--offset',str(off)])
    contacts.extend(data['contacts'])
    total=data.get('metadata',{}).get('total')
    if total is not None:
        meta_total=total
        if len(contacts)>=total: break
print('num contacts', len(contacts), 'total', meta_total, file=sys.stderr)
full_to_contacts=defaultdict(list)
for c in contacts:
    full=(c.get('first_name','')+' '+c.get('last_name','')).strip()
    full_to_contacts[full].append(c)
# get names for unique participant ids
ids=sorted({pid for conv in convs for pid in conv['participant_ids']})
id_to_name={}
for pid in ids:
    name=run_json(['chats','get-user-name-from-id','--user-id',pid])
    id_to_name[pid]=name
# current user ids from contacts is_user names; also from participant common?
current_names={ (c['first_name']+' '+c['last_name']).strip() for c in contacts if c.get('is_user') }
print('current_names', current_names, file=sys.stderr)
# count participant occurrences in 35 convs for contacts, excluding is_user
counts=Counter()
id_contact={}
for conv in convs:
    for pid in conv['participant_ids']:
        name=id_to_name[pid]
        matches=full_to_contacts.get(name, [])
        if matches:
            # exclude current user contacts
            if any(c.get('is_user') for c in matches):
                continue
            counts[name]+=1
            id_contact[pid]=matches[0]
# print ranking
print('\nCHAT participant contact counts:', file=sys.stderr)
for name,count in sorted(counts.items(), key=lambda kv:(-kv[1], kv[0])):
    c=full_to_contacts[name][0]
    print(count, name, 'city=',c.get('city_living'),'age=',c.get('age'), file=sys.stderr)
# For each chat-ranked person/city in order, find youngest contact from city on Messages, alphabetically among ties, then most recent conversation
ranked=sorted(counts.items(), key=lambda kv:(-kv[1], kv[0]))
# Cache messages exact user ids and conversations
msg_uid_cache={}
msg_conv_cache={}
def msg_uid(name):
